 class eventclass_matriculas_semestre  extends eventsBase
{
	function __construct()
	{
	// fill list of events
		$this->events["AfterAdd"]=true;

		$this->events["BeforeQueryList"]=true;

		$this->events["BeforeAdd"]=true;

		$this->events["BeforeShowList"]=true;



	}

//	handlers

		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
				// After record added
function AfterAdd(&$values, &$keys, $inline, &$pageObject)
{

		$matricula_id  = intval($keys["id"]);
$estudiante_id = intval($values["estudiante_id"]);
$carrera_id    = intval($values["carrera_id"]);
$semestre      = intval($values["semestre"]);
$periodo_id    = intval($values["periodo_id"]);

// 1. Inscribir automáticamente las materias del semestre respetando cupos
$sqlCursos = "SELECT c.id AS curso_id, c.cupo, COUNT(i.id) AS inscriptos 
              FROM cursos c 
              INNER JOIN carrera_materia cm ON cm.materia_id = c.materia_id 
                                           AND cm.carrera_id = " . $carrera_id . " 
                                           AND cm.semestre = " . $semestre . " 
              LEFT JOIN inscripciones i ON i.curso_id = c.id 
              WHERE c.periodo_id = " . $periodo_id . " 
                AND (c.carrera_id = " . $carrera_id . " OR c.carrera_id IS NULL) 
                AND c.estado = 'Activo' 
              GROUP BY c.id, c.cupo";
$rs = DB::Query($sqlCursos);

while ($data = $rs->fetchAssoc()) {
    $curso_id = intval($data["curso_id"]);
    $cupoMax  = intval($data["cupo"]);
    $actuales = intval($data["inscriptos"]);
    
    // Solo inscribir si hay cupo disponible
    if ($actuales < $cupoMax) {
        $data_ins = array();
        $data_ins["matricula_semestre_id"] = $matricula_id;
        $data_ins["estudiante_id"]          = $estudiante_id;
        $data_ins["curso_id"]               = $curso_id;
        $data_ins["fecha_inscripcion"]      = date("Y-m-d H:i:s");
        DB::Insert("inscripciones", $data_ins);
    }
}

// 2. Generación de Cuenta Corriente (1 Matrícula anual + N Cuotas)
$sqlCar = "SELECT costo_matricula, costo_semestre, cantidad_cuotas FROM carreras WHERE id = " . $carrera_id . " LIMIT 1";
$rsCar = DB::Query($sqlCar);

if ($car = $rsCar->fetchAssoc()) {
    $costo_mat  = intval($car["costo_matricula"]);
    $costo_sem  = intval($car["costo_semestre"]);
    $cant_cuot  = intval($car["cantidad_cuotas"]) > 0 ? intval($car["cantidad_cuotas"]) : 5;
    $monto_cuota = intval(round($costo_sem / $cant_cuot));
    $año_actual = date("Y");

    // A. Cobro de Matrícula (una sola vez por año lectivo)
    $sqlCheckMat = "SELECT p.id FROM pagos p 
                    INNER JOIN conceptos_pago cp ON cp.id = p.concepto_id 
                    WHERE p.estudiante_id = " . $estudiante_id . " 
                      AND cp.nombre LIKE '%Matr%' 
                      AND YEAR(p.fecha_vencimiento) = " . intval($año_actual) . " LIMIT 1";
    $rsCheckMat = DB::Query($sqlCheckMat);
    
    if (!$rsCheckMat->fetchAssoc() && $costo_mat > 0) {
        $concepto_mat_id = 1;
        $rsConMat = DB::Query("SELECT id FROM conceptos_pago WHERE nombre LIKE '%Matr%' LIMIT 1");
        if ($rM = $rsConMat->fetchAssoc()) {
            $concepto_mat_id = intval($rM["id"]);
        }

        $pagoMat = array();
        $pagoMat["estudiante_id"]         = $estudiante_id;
        $pagoMat["matricula_semestre_id"] = $matricula_id;
        $pagoMat["periodo_id"]            = $periodo_id;
        $pagoMat["concepto_id"]           = $concepto_mat_id;
        $pagoMat["nro_cuota"]             = "Matrícula";
        $pagoMat["monto"]                 = $costo_mat;
        $pagoMat["descuento"]             = 0;
        $pagoMat["multa_mora"]            = 0;
        $pagoMat["fecha_vencimiento"]     = date("Y-m-d", strtotime("+10 days"));
        $pagoMat["estado"]                = "Pendiente";
        DB::Insert("pagos", $pagoMat);
    }

    // B. Cuotas Mensuales del Semestre (Día 10 de cada mes)
    $concepto_cuota_id = 2;
    $rsConCuota = DB::Query("SELECT id FROM conceptos_pago WHERE nombre LIKE '%Mensual%' OR nombre LIKE '%Cuota%' LIMIT 1");
    if ($rC = $rsConCuota->fetchAssoc()) {
        $concepto_cuota_id = intval($rC["id"]);
    }

    $mes_base = date("m");
    $año_base = date("Y");

    for ($i = 1; $i <= $cant_cuot; $i++) {
        $pagoCuota = array();
        $pagoCuota["estudiante_id"]         = $estudiante_id;
        $pagoCuota["matricula_semestre_id"] = $matricula_id;
        $pagoCuota["periodo_id"]            = $periodo_id;
        $pagoCuota["concepto_id"]           = $concepto_cuota_id;
        $pagoCuota["nro_cuota"]             = sprintf("%02d/%02d", $i, $cant_cuot);
        $pagoCuota["monto"]                 = $monto_cuota;
        $pagoCuota["descuento"]             = 0;
        $pagoCuota["multa_mora"]            = 0;
        $pagoCuota["fecha_vencimiento"]     = date("Y-m-10", strtotime("+" . ($i - 1) . " month", strtotime("$año_base-$mes_base-01")));
        $pagoCuota["estado"]                = "Pendiente";
        DB::Insert("pagos", $pagoCuota);
    }
}
;		
} // function AfterAdd

		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		

		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
				// List page: Before SQL query
function BeforeQueryList(&$strSQL, &$strWhereClause, &$strOrderBy, &$pageObject)
{

		// Alumno: solo ve sus propias matrículas semestrales
if ($_SESSION["rol"] == 'Alumno') {
    $strWhereClause = whereAdd($strWhereClause, "estudiante_id = " . intval($_SESSION["estudiante_id"]));
}
;		
} // function BeforeQueryList

		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		

		
		
		
		
		
		
		
		
		
		
		
		
		
				// Before record added
function BeforeAdd(&$values, &$message, $inline, &$pageObject)
{

		$est_id   = intval($values["estudiante_id"]);
$periodo  = intval($values["periodo_id"]);
$semestre = intval($values["semestre"]);

if ($est_id <= 0 || $periodo <= 0 || $semestre <= 0) {
    $message = "Debe especificar el estudiante, periodo y semestre.";
    return false;
}

// 1. Evitar duplicar matrícula en el mismo periodo
$rsDup = DB::Query("SELECT id FROM matriculas_semestre WHERE estudiante_id = " . $est_id . " AND periodo_id = " . $periodo . " LIMIT 1");
if ($rsDup->fetchAssoc()) {
    $message = "El estudiante ya posee una matrícula registrada para este periodo académico.";
    return false;
}

if (empty($values["fecha_matricula"])) {
    $values["fecha_matricula"] = date("Y-m-d H:i:s");
}
if (empty($values["estado"])) {
    $values["estado"] = "Activo";
}

return true;
;		
} // function BeforeAdd

		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		

		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
