$pageObject->setProxyValue("user_rol", $rol_actual);

if ($rol_actual != "Admin" && $rol_actual != "Secretaria") {
    $pageObject->hideItem("custom_button");
}
;		
} // function BeforeShowList

		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		

		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		



